//! 🧪️ Stable own IFC2x3 selection edits and readonly inspector metadata.
use super::*;
use semio_s_artifact_stdio_contract::part21::{Part21Document,Part21Instance};
use semio_s_artifact_stdio_ifc_2x3_base_mutations::standards::v2x3::subsets::base::schema::mutations::Ifc2x3Mutation;
fn snapshot()->Ifc2x3Snapshot{Ifc2x3Snapshot{document:Part21Document{instances:vec![Part21Instance{id:1,entities:vec![("IFCWALL".into(),vec![Part21Value::Unset;8])]},Part21Instance{id:u64::MAX,entities:vec![("IFCLOCALPLACEMENT".into(),vec![Part21Value::Unset;2])]}],..Default::default()},..Default::default()}}
#[test]
fn neutral_exact_identity_and_row_reorder_use_own_snapshot_paths(){let fixture:semio_framework_pack_json::Value=semio_framework_pack_json::parse(include_str!("🔣️.json"),semio_framework_pack_json::JsonMemberPolicy::Reject).unwrap();let mut snapshot=snapshot();let pointer=format!("/{}{}",fixture["identity"].as_str().unwrap(),fixture["suffix"].as_str().unwrap());let event=SnapshotEditEvent::SetValue{path:pointer,value:DslValue::String("9".into())};assert_eq!(selected_edit_admission(&event),Some(true));let Some(SnapshotEditEvent::SetValue{path,..})=selected_edit_controlled(&event,&snapshot,&mut ||Ok(())).unwrap()else{panic!("selected event not translated")};assert_eq!(path,format!("/document/instances/1{}",fixture["suffix"].as_str().unwrap()));snapshot.document.instances.reverse();let Some(SnapshotEditEvent::SetValue{path,..})=selected_edit_controlled(&event,&snapshot,&mut ||Ok(())).unwrap()else{panic!("reordered selected event not translated")};assert_eq!(path,format!("/document/instances/0{}",fixture["suffix"].as_str().unwrap()));for value in fixture["rejected"].as_array().unwrap(){assert!(identity::parse_ifc_entity_identity(value.as_str().unwrap()).is_none());}assert!(selected_edit_controlled(&event,&snapshot,&mut ||Err("cancelled".into())).is_err());}
#[test]
fn selected_typed_attribute_reaches_existing_own_instance_mutation(){use semio_s_artifact_stdio_contract::editing::SnapshotEditingEditor;type Editor=crate::editor::ifc2x3_any::Ifc2x3AnyEditor;let mut snapshot=snapshot();snapshot.document.instances.reverse();let event=SnapshotEditEvent::SetValue{path:"/ifc-1/entities/0/arguments/2".into(),value:Part21Value::Str("Changed wall".into()).to_value()};assert!(Editor::snapshot_edit_is_admitted(&event,&snapshot));let emit=Editor::snapshot_edit_emit(&event,&snapshot).unwrap();assert!(matches!(&emit.artifact_mutations[0],Ifc2x3Mutation::UpsertInstance(change)if change.instance.id==1&&change.instance.entities[0].1[2]==Part21Value::Str("Changed wall".into())));let topology=topology(&snapshot);assert!(topology.domains[DOMAIN].ordered.iter().any(|node|node.id==format!("ifc-{}",u64::MAX)));}
#[test]
fn viewer_provider_is_readonly_and_manifests_declare_the_real_topology_domain(){let snapshot=snapshot();let provider=Provider{details:Ifc2x3DetailsProvider::new(&snapshot),id:1,row:0,editable:false};let path=[P::Key("ifc-1".into()),P::Key("entities".into()),P::Index(0),P::Key("arguments".into()),P::Index(2)];assert!(!provider.item_capabilities(&path).edit);assert_eq!(provider.variant_count(&path,Locale::En),0);assert!(!provider.has_source());for definition in [crate::editor::ifc2x3_any::create_ifc2x3_any_editor(),crate::viewer::ifc2x3_any::create_ifc2x3_any_viewer()]{assert!(definition.interactions.iter().any(|domain|domain.id==DOMAIN));assert!(definition.window_kinds.iter().any(|window|window.body_key==BODY_KEY));}}
